func moeGEMVPushConstants(N, K, block, ldw, lda, groupBase int, xScale float32) []byte {
	pc := newPC().U32(uint32(N)).U32(uint32(K)).U32(log2u(block)).F32(xScale).
		U32(uint32(ldw)).U32(uint32(lda)).U32(uint32(groupBase)).Bytes()
