// and nothing else.
const moeStrideTokens = 2048

// moeMinIters matches the shapes family's floor and for the same reason: the
// small-token cases here run for tens of microseconds, and at that length the
// suite's default of 20 iterations has been measured disagreeing with itself
// by up to 105% on its worst cell.
const moeMinIters = 200

// RunMoE measures the grouped GEMM, the per-expert baseline it replaces, and
// the gather/combine passes it needs (IDEAS §3.5).
func RunMoE(dev *vk.Device, phys *vk.PhysicalDevice, warmup, iters uint32) ([]Result, error) {
	if iters < moeMinIters {
		iters = moeMinIters
	}
	shape, ok, err := findCoopMatShape(phys, vk.ComponentFloat16, vk.ComponentFloat32)
	if err != nil {
		return nil, err
	}
	if !ok || shape.M != 16 || shape.N != 16 || shape.K != 16 {
		fmt.Fprintln(os.Stderr, "moe: no 16x16x16 cooperative-matrix shape, skipping")
		return nil, nil
	}

	// The prefill batches and the decode ones (IDEAS §3.5's open item, run by
	// bench/ops_moe_gemv.go) share one routing per token count: the two lists
	// overlap at t=1, and the same seed there means the GEMV arm and the GEMM
	// arm are measured over the same assignment rather than over two draws
	// of it.
	q4Tokens := mergeTokens(moeTokens, moeDecodeTokens)
	routings := make(map[int]moeRouting, len(q4Tokens))
	for _, t := range q4Tokens {
		routings[t] = routeTokens(t)
	}

	results, err := runMoERoute(dev, routings, warmup, iters)
	if err != nil {
		return nil, err
	}

	variants := filterWaveVariants(moeVariants, mustSubgroupSizeControl(phys),
		func(v moeVariant) (string, uint32) { return "moe " + v.name, v.waveSize })

	for _, s := range moeShapes {
		rs, err := runMoEShape(dev, s, variants, routings, warmup, iters)
		if err != nil {
			return nil, err
		}
		results = append(results, rs...)
	}

	// The Q4 arm (IDEAS §2.2), in its own loop so that its ~1-2 GB of
	// buffers are allocated after the fp16 bank's 2-4 GB have been freed
	// rather than alongside them.
	q4 := filterWaveVariants(moeQ4Variants, mustSubgroupSizeControl(phys),
		func(v moeQ4Variant) (string, uint32) { return "moe " + v.name, v.waveSize })
	for _, s := range moeShapes {
		// The decode batches are in this list as well as the prefill ones,
		// because "decode runs the grouped GEMM at M=1" is the claim the GEMV
		// arm below is measured against and it has to be measured, not
		// assumed.
		rs, err := runMoEShapeQ4(dev, s, q4, routings, q4Tokens, warmup, iters)
		if err != nil {
			return nil, err
		}
		results = append(results, rs...)
	}

	// The grouped GEMV: the decode kernel §3.5 said this family needed and did
	// not have (bench/ops_moe_gemv.go).
	gemv := filterWaveVariants(moeGEMVVariants, mustSubgroupSizeControl(phys),
		func(v moeGEMVVariant) (string, uint32) { return "moe " + v.name, v.waveSize })
	for _, s := range moeShapes {
		rs, err := runMoEShapeGEMV(dev, s, gemv, routings, moeDecodeTokens, warmup, iters)
		if err != nil {
			return nil, err
		}
		results = append(results, rs...)
	}
	return results, nil
}

// mergeTokens unions two batch lists, in ascending order.
func mergeTokens(a, b []int) []int {
	seen := map[int]bool{}
	var out []int
	for _, list := range [][]int{a, b} {
		for _, t := range list {
			if !seen[t] {
				seen[t] = true
				out = append(out, t)
			}
		}
	}
	sort.Ints(out)
	return out
}

// ---------------------------------------------------------------------------
// Routing
// ---------------------------------------------------------------------------

// moeRouting is one batch's top-k assignment: for each expert, which token
// rows were routed to it.
//
// The assignment is uniform-random rather than exactly balanced, because
// balance is the thing under test. Uniform top-k over 512 experts makes each
// expert's count Poisson-ish around tokens*topk/experts, so at the real
// prefill an expert gets 40 rows on average and 60-odd at the tail — and a
// per-expert dispatch loop pays for the tail twice over, once in tile padding
// and once in the dispatch that runs alone.

